local config = {
  ui_story_5050_50500001_1_dialog_content = "<color=#e8d9bb>Generating scene...</color>",
  ui_story_5050_50500001_2_dialog_content = "<color=#e8d9bb>Generating final script...</color>",
  ui_story_5050_50500001_3_dialog_content = "<color=#e8d9bb>Welcome to the <color=#FFB400>Co-op Training Simulator</color>.</color>",
  ui_story_5050_50500001_4_dialog_content = "It's hard to believe, but this place is identical to the actual Umbraton. Even the residents passing by in the streets have been perfectly simulated.",
  ui_story_5050_50500001_5_dialog_content = "Unfortunately, you cannot engage in normal conversations with all of the townspeople.",
  ui_story_5050_50500001_6_dialog_content = "It appears that all of the buildings can be accessed, and we can search for targets across various zones.",
  ui_story_5050_50500001_7_dialog_content = "But this may reduce our efficiency, as many places are useless for the mission.",
  ui_story_5050_50500001_8_dialog_content = "Not a problem—we can send 01 and the others to search for us.",
  ui_story_5050_50500001_9_dialog_content = "Friends, this is not the time for idle banter. Standing around instead of taking immediate action? Well, that's just not how knights do things.",
  ui_story_5050_50500001_10_dialog_content = "Don't forget why we're here in this simulator. No matter how large your workload is, you have to start somewhere.",
  ui_story_5050_50500001_11_dialog_content = "Very true, but doing useless work is also a waste of time. Isn't this design rather pointless?",
  ui_story_5050_50500001_12_dialog_content = "I don't know what \"she\" was thinking either...",
  ui_story_5050_50500101_1_dialog_content = "<color=#e8d9bb>Not long ago...</color>",
  ui_story_5050_50500101_2_dialog_content = "What was so important that you felt you needed to call us over during break time?",
  ui_story_5050_50500101_3_dialog_content = "Heehee, let's have a look—all the teams are here!",
  ui_story_5050_50500101_4_dialog_content = "Can you stop with the sinister laugh? You're creeping me out! This had better be something major for you to take up everyone's break like this.",
  ui_story_5050_50500101_5_dialog_content = "Calm down, everyone. I actually have some good news for you all.",
  ui_story_5050_50500101_6_dialog_content = "I know better than anyone that break time is the most precious time of all, so I'll make this as short as possible. Basically, I've created a brand new version of the Battle Simulator.",
  ui_story_5050_50500101_7_dialog_content = "The simulator? You want us to do combat training right now?",
  ui_story_5050_50500101_8_dialog_content = "That's it! But this version's different from the basic battle exercises you were doing before, as combat is only one part of it.",
  ui_story_5050_50500101_9_dialog_content = "I added a game—coughs, I mean, I designed a heap of map exploration quests, co-op missions, and puzzle stages.",
  ui_story_5050_50500101_10_dialog_content = "Victory isn't always won through brute force. Teamwork and brainwork are also very important.",
  ui_story_5050_50500101_11_dialog_content = "Compared to traditional battle simulators, I believe this Co-op Training Simulator has the potential to comprehensively train everyone's abilities.",
  ui_story_5050_50500101_12_dialog_content = "That's why I wanted to invite everyone to give it a try—you'll also be helping me with the testing at the same time!",
  ui_story_5050_50500101_13_dialog_content = "What? You haven't even tested it yet?",
  ui_story_5050_50500101_14_dialog_content = "I did some simple testing by myself, but I need more people to conduct some in-depth testing for me.",
  ui_story_5050_50500101_15_dialog_content = "Rest assured that this training sim won't affect the actual results of the Joint Military Exercise—it's just a personal request from yours truly!",
  ui_story_5050_50500101_16_dialog_content = "I must admit that this is actually a rare opportunity, and to be honest, we're also in dire need of some extra training.",
  ui_story_5050_50500101_17_dialog_content = "If this is indeed an opportunity for extra training, we shouldn't let it slip by. Personally, I have no objection whatsoever.",
  ui_story_5050_50500101_18_dialog_content = "If everyone's in, let's start drawing straws. Due to the nature of the puzzles you'll be tackling, only two teams can enter at once.",
  ui_story_5050_50500101_19_dialog_content = "<color=#e8d9bb>Everyone quickly proceeds to draw straws in order to decide which teams will go first.</color>",
  ui_story_5050_50500101_20_dialog_content = "Let me see... Alright, Team Twilight and Team Yingel—you're up first!",
  ui_story_5050_50500101_21_dialog_content = "Haha, very nice. That's absolutely fine by me.",
  ui_story_5050_50500101_22_dialog_content = "I should be able to learn a lot from training alongside a knight captain.",
  ui_story_5050_50500101_23_dialog_content = "So, the other teams should leave for now—you wouldn't want to see the answers before getting a chance to try for yourselves, would you?",
  ui_story_5050_50500101_24_dialog_content = "Without further ado, let's get started!",
  ui_story_5050_50500101_25_dialog_content = "This is no ordinary battle training. What are the rules?",
  ui_story_5050_50500101_26_dialog_content = "Oh, right, I almost forgot about that... But as soon as you enter, you'll realize for yourselves that the maps this time are constantly changing.",
  ui_story_5050_50500101_27_dialog_content = "You mean there are different maps?",
  ui_story_5050_50500101_28_dialog_content = "I've designed a total of <color=#FFB400>six main stages</color>, each based on a different region.",
  ui_story_5050_50500101_29_dialog_content = "Everyone needs to explore the map and complete the stage's <color=#FFB400>quests</color>. Your goal is to reach the finish line and claim all the supplies and rewards!",
  ui_story_5050_50500101_30_dialog_content = "You'll be equipped with a communicator for this simulation, allowing you to communicate remotely.",
  ui_story_5050_50500101_31_dialog_content = "It sounds quite easy, just like a game.",
  ui_story_5050_50500101_32_dialog_content = "D-Don't focus too much on these little details, it won't be as simple as you might imagine.",
  ui_story_5050_50500101_33_dialog_content = "Both teams will need to work together to operate certain mechanisms in special areas. This will be the moment your ability to work together is tested!",
  ui_story_5050_50500101_34_dialog_content = "It all still sounds a little ambiguous to me. Let's enter the simulator and take a look for ourselves.",
  ui_story_5050_50500101_35_dialog_content = "Right, I could talk about the details forever! Come on then! After you get in there, explore at your own pace and you'll soon know all there is to know.",
  ui_story_5050_50500101_36_dialog_content = "Since every building can be accessed at will, it seems like we'll have to visit each one of them.",
  ui_story_5050_50500101_37_dialog_content = "Hey! Can everyone hear me?",
  ui_story_5050_50500101_38_dialog_content = "See the Quest Points and Resource Points on the map? I've adjusted these key areas so that they'll automatically prompt you as to their locations.",
  ui_story_5050_50500101_39_dialog_content = "Gronru can hear everything we were saying?",
  ui_story_5050_50500101_40_dialog_content = "This should greatly increase efficiency, so the other teams won't be kept waiting outside for too long.",
  ui_story_5050_50500101_41_dialog_content = "Thank you.",
  ui_story_5050_50500101_42_dialog_content = "Hehe, I really didn't intend that during the development process! Come on, everyone—you can do it!",
  ui_story_5050_50500101_43_dialog_content = "Let's get started too, and try not to miss these marked areas.",
  ui_story_5050_50500101_44_dialog_content = "Each of the rooms that can be entered is different from its counterpart in the real Umbraton, so be extra careful.",
  ui_story_5050_50500101_45_dialog_content = "There seems to be a special quest among them. May the God of Light bless you.",
  ui_story_5050_50500101_46_dialog_content = "It's okay, I've got this.",
  ui_story_5050_50500101_47_dialog_content = "Alright, let our spirits soar to the limits of the sky! Let's finish this in one fell swoop!",
  ui_story_5050_50500102_1_dialog_content = "I think we're about to reach the next stage. Is everyone still in tip-top shape?",
  ui_story_5050_50500102_2_dialog_content = "No problems over here.",
  ui_story_5050_50500102_3_dialog_content = "We're good too.",
  ui_story_5050_50500102_4_dialog_content = "I'm gradually getting to grips with the ins and outs of this training. With all the different kinds of stages, they could be challenging.",
  ui_story_5050_50500102_5_dialog_content = "I guess Gronru designed the first stage to let us experience the rules. The next stage may not be so easy.",
  ui_story_5050_50500102_6_dialog_content = "I concur.",
  ui_story_5050_50500102_7_dialog_content = "Haha! Let's just focus on what we need to do, no matter what comes our way.",
  ui_story_5050_50500102_8_dialog_content = "So everyone, onward to the next stage!",
  ui_story_5050_50500201_1_dialog_content = "This is... PlayerName's Soroz!",
  ui_story_5050_50500201_2_dialog_content = "I can't believe she even has the blueprints here.",
  ui_story_5050_50500201_3_dialog_content = "Gronru is extremely competent. Never underestimate her.",
  ui_story_5050_50500201_4_dialog_content = "We have a problem.",
  ui_story_5050_50500201_5_dialog_content = "This seems to be the master-control room, but the door is sealed. That means we cannot go directly to another location on Soroz.",
  ui_story_5050_50500201_6_dialog_content = "There's no way this stage is limited to just one room. There should be something hidden around here, such as a clue or some kind of mechanism.",
  ui_story_5050_50500201_7_dialog_content = "I see. Just search the place.",
  ui_story_5050_50500201_8_dialog_content = "What do you think, Yingel?",
  ui_story_5050_50500201_9_dialog_content = "Oh, I didn't think you'd be interested in hearing my opinion. The master-control room barely has any fixtures or furnishings, so the only place any clues could possibly be hidden is in the control panel.",
  ui_story_5050_50500201_10_dialog_content = "You hit the nail on the head! I think the control panel seems quite suspicious too.",
  ui_story_5050_50500201_11_dialog_content = "Yingel's right, there's a mechanical box under the panel.",
  ui_story_5050_50500201_12_dialog_content = "I know this is just virtual reality, but this box is beautiful.",
  ui_story_5050_50500201_13_dialog_content = "There's nowhere to enter a password or unlock it. Maybe we need to open it through some other method?",
  ui_story_5050_50500201_14_dialog_content = "Hmm, I've seen similar experimental items before. Maybe it's voice-controlled.",
  ui_story_5050_50500201_15_dialog_content = "Voice-controlled? That means it still requires a password. Axelia, would you like to give it a try?",
  ui_story_5050_50500201_16_dialog_content = "Hmm... Password, master-control room.",
  ui_story_5050_50500201_17_dialog_content = "Incorrect password. Please try again.",
  ui_story_5050_50500201_18_dialog_content = "Password, Soroz.",
  ui_story_5050_50500201_19_dialog_content = "Incorrect password. Please try again.",
  ui_story_5050_50500201_20_dialog_content = "Guessing at random doesn't seem to be a feasible solution. Are there any other clues on the panel?",
  ui_story_5050_50500201_21_dialog_content = "... Hmm, I've found a clue here that looks like a password.",
  ui_story_5050_50500201_22_dialog_content = "That's great, Leo. Well, let's not waste any more time...",
  ui_story_5050_50500201_23_dialog_content = "Yingel, maybe you should read it.",
  ui_story_5050_50500201_24_dialog_content = "Hmm? Alright, then. Let me have a look.",
  ui_story_5050_50500201_25_dialog_content = "...",
  ui_story_5050_50500201_26_dialog_content = "What's the matter, Yingel? Please read it out quickly.",
  ui_story_5050_50500201_27_dialog_content = "Heavens, is it something embarrassing?",
  ui_story_5050_50500201_28_dialog_content = "(The quest is all that matters, nothing else is important...!)",
  ui_story_5050_50500201_29_dialog_content = "Password, \"Who's the strongest in the land? The spectacular sparkling beautiful maiden, Gronru, of the game world! Kira-Kira!\"",
  ui_story_5050_50500201_30_dialog_content = "...",
  ui_story_5050_50500201_31_dialog_content = "...",
  ui_story_5050_50500201_32_dialog_content = "I'm truly sorry.",
  ui_story_5050_50500201_33_dialog_content = "<color=#e8d9bb>Rumble—</color>",
  ui_story_5050_50500201_34_dialog_content = "<size=45>What's that?!</size>",
  ui_story_5050_50500201_35_dialog_content = "Is it an earthquake?",
  ui_story_5050_50500201_36_dialog_content = "<size=45>Keep your footing, everyone! Hold on to me!</size>",
  ui_story_5050_50500201_37_dialog_content = "Unlock command activated. Please separate into your respective teams on either side of the room. Teleporting in fifteen seconds—",
  ui_story_5050_50500201_38_dialog_content = "Ugh!",
  ui_story_5050_50500201_39_dialog_content = "Cough...",
  ui_story_5050_50500201_40_dialog_content = "It seems we've been teleported to another room. If I'm not mistaken, it should be somewhere similar to the lounge.",
  ui_story_5050_50500201_41_dialog_content = "How come Miss Yingel and Axelia are not here?",
  ui_story_5050_50500201_42_dialog_content = "Leo, can you hear me?",
  ui_story_5050_50500201_43_dialog_content = "We seem to have been assigned to different rooms. Are you okay over there?",
  ui_story_5050_50500201_44_dialog_content = "We're fine. So, this is what the communicators are for.",
  ui_story_5050_50500201_45_dialog_content = "There's something you should know. If we want to continue moving forward, it seems we'll need your support.",
  ui_story_5050_50500201_46_dialog_content = "Is this the cooperation she mentioned earlier?",
  ui_story_5050_50500201_47_dialog_content = "I'm afraid so, please complete the quest on your end as soon as possible.",
  ui_story_5050_50500201_48_dialog_content = "Hmm, let's get started as quickly as we can.",
  ui_story_5050_50500201_49_dialog_content = "...",
  ui_story_5050_50500201_50_dialog_content = "What's wrong, Axelia? Are you feeling okay?",
  ui_story_5050_50500201_51_dialog_content = "It's alright, I just stumbled during the teleportation. Let's go.",
  ui_story_5050_50500202_1_dialog_content = "Things have been progressing quite smoothly so far. Are you all okay?",
  ui_story_5050_50500202_2_dialog_content = "Don't worry, I'm fi—cough, cough.",
  ui_story_5050_50500202_3_dialog_content = "Are you sure?",
  ui_story_5050_50500202_4_dialog_content = "Zhao, if you're not feeling well, be sure to let us know at any time.",
  ui_story_5050_50500202_5_dialog_content = "Hehe, I'm not that fragile, don't worry.",
  ui_story_5050_50500202_6_dialog_content = "Leo, we just need to maintain our current pace. There's no need to rush.",
  ui_story_5050_50500202_7_dialog_content = "This is training, isn't it? How can we treat it casually, especially when Team Yingel is giving it their all?",
  ui_story_5050_50500202_8_dialog_content = "Yes, and now, because of her, both sides are working hard to overcome this challenge.",
  ui_story_5050_50500202_9_dialog_content = "Alright, since everything's fine, let's continue moving forward.",
  ui_story_5050_50500203_1_dialog_content = "We should be able to clear this stage soon.",
  ui_story_5050_50500203_2_dialog_content = "Right, we can already see the exit.",
  ui_story_5050_50500203_3_dialog_content = "Yingel, how are things progressing on your end?",
  ui_story_5050_50500203_4_dialog_content = "Things are going smoothly at present. We're almost at the exit.",
  ui_story_5050_50500203_5_dialog_content = "Thanks to all of you, that is.",
  ui_story_5050_50500203_6_dialog_content = "The difficulty has increased significantly compared to before. Even the Eclipsites are stronger this time.",
  ui_story_5050_50500203_7_dialog_content = "Isn't that for the best? When it comes to training, ordinary Eclipsites just don't cut it anymore.",
  ui_story_5050_50500203_8_dialog_content = "However, the quests and resource-gathering aspects have been going smoothly so far, so keep it up, everyone.",
  ui_story_5050_50500203_9_dialog_content = "The next stage might be more challenging.",
  ui_story_5050_50500204_1_dialog_content = "Speaking of which, I didn't expect to find such an interesting room aboard Soroz.",
  ui_story_5050_50500204_2_dialog_content = "Well, if that Caelestite can live on this Colossus and even receive numerous guests here, it's not surprising that it boasts comprehensive facilities.",
  ui_story_5050_50500204_3_dialog_content = "...",
  ui_story_5050_50500204_4_dialog_content = "Axelia, is it my imagination, or have you been feeling a little out of sorts?",
  ui_story_5050_50500204_5_dialog_content = "I'm okay. Everything's okay.",
  ui_story_5050_50500204_6_dialog_content = "Are you sure? If you're feeling unwell, just let us know.",
  ui_story_5050_50500204_7_dialog_content = "I'm sure. I had plenty of rest before entering the simulator, and I can take a lot more than what we've been through so far.",
  ui_story_5050_50500204_8_dialog_content = "Let's just focus on the task at hand.",
  ui_story_5050_50500204_9_dialog_content = "If Axelia says so, let's hurry forward.",
  ui_story_5050_50500204_10_dialog_content = "... Hmm. Don't push yourself too hard, though.",
  ui_story_5050_50500205_1_dialog_content = "The exit of this stage should be ahead.",
  ui_story_5050_50500205_2_dialog_content = "Anatoli, are you drawing a map?",
  ui_story_5050_50500205_3_dialog_content = "Yes, I've made a complete record of the current terrain.",
  ui_story_5050_50500205_4_dialog_content = "But this is just a personal habit of mine. I'm afraid it won't be of much use.",
  ui_story_5050_50500205_5_dialog_content = "In actual combat, it's a good habit to immediately plan alternative escape routes in an emergency.",
  ui_story_5050_50500205_6_dialog_content = "Sigh...",
  ui_story_5050_50500205_7_dialog_content = "Axelia, let's take a break. There's no need for us to overexert ourselves.",
  ui_story_5050_50500205_8_dialog_content = "There's really no need. Leo's team has already moved on to the next stage. There's no good reason we should be lagging behind them.",
  ui_story_5050_50500205_9_dialog_content = "Besides, this is a co-op exercise, so we shouldn't cause any unnecessary delays.",
  ui_story_5050_50500205_10_dialog_content = "Well, if you insist, let's proceed to the next stage.",
  ui_story_5050_50500205_11_dialog_content = "But don't force yourself—just let me know when you need a break.",
  ui_story_5050_50500205_12_dialog_content = "If anything happens to you, it'll affect our progress much more than taking a short break.",
  ui_story_5050_50500205_13_dialog_content = "Understood.",
  ui_story_5050_50500301_1_dialog_content = "Is this Gannon City?",
  ui_story_5050_50500301_2_dialog_content = "I really miss this place. It's been a while since I've been back to Gannon City.",
  ui_story_5050_50500301_3_dialog_content = "It's embarrassing, but I've been giving alms across the continent for such a long time and haven't visited Gannon City very much at all.",
  ui_story_5050_50500301_4_dialog_content = "I feel the same way.",
  ui_story_5050_50500301_5_dialog_content = "I practically grew up here, and although I've also been through a lot, it still holds a special place in my heart.",
  ui_story_5050_50500301_6_dialog_content = "You don't seem to be doing too well. How did you survive the training at the Illumina barracks?",
  ui_story_5050_50500301_7_dialog_content = "If it weren't for those borderline sadistic experiences, I wouldn't be who I am today. Cough, cough...",
  ui_story_5050_50500301_8_dialog_content = "I gradually developed my own combat style after being thrust into various battle scenarios.",
  ui_story_5050_50500301_9_dialog_content = "I also learned how to strategize and command battles.",
  ui_story_5050_50500301_10_dialog_content = "That's truly amazing, I hope the light always shines on you.",
  ui_story_5050_50500301_11_dialog_content = "Hey! Sounds like you guys are having a great conversation in there!",
  ui_story_5050_50500301_12_dialog_content = "Just a friendly tip, there'll be no support segments at this stage, so you can go ahead and arrange your strategy for yourselves.",
  ui_story_5050_50500301_13_dialog_content = "Understood.",
  ui_story_5050_50500301_14_dialog_content = "So, let's push forward with all our might.",
  ui_story_5050_50500302_1_dialog_content = "Cough, cough... Cough, cough, cough...",
  ui_story_5050_50500302_2_dialog_content = "The Eclipsites were clearly much stronger in the battle just now. Let's take a break.",
  ui_story_5050_50500302_3_dialog_content = "... You don't need to stop for my sake. I'm alright.",
  ui_story_5050_50500302_4_dialog_content = "I didn't say it was because of you.",
  ui_story_5050_50500302_5_dialog_content = "You don't need to be so considerate, Captain Leo. The task at hand is crucial, though I do appreciate your kindness. Cough...!",
  ui_story_5050_50500302_6_dialog_content = "When you need to rest, trying to fight through it will only burden the rest of the team.",
  ui_story_5050_50500302_7_dialog_content = "What do you mean by that? Are you trying to say I'm a burden?",
  ui_story_5050_50500302_8_dialog_content = "Oh! Calm down, everyone, please.",
  ui_story_5050_50500302_9_dialog_content = "Your intentions here are all good. We're all children of the God of Light, so let's please maintain harmony.",
  ui_story_5050_50500302_10_dialog_content = "...",
  ui_story_5050_50500302_11_dialog_content = "It's okay. I know you can't force others to act against their will. Let's move on.",
  ui_story_5050_50500303_1_dialog_content = "Thank the heavens—it seems like we're about to reach the exit.",
  ui_story_5050_50500303_2_dialog_content = "...",
  ui_story_5050_50500303_3_dialog_content = "(Leo has a powerful personality, and Zhao can occasionally become quite sensitive due to his physical stimulus, though he seems down to earth most of the time.)",
  ui_story_5050_50500303_4_dialog_content = "(The atmosphere has been a bit tense since just now. I hope these two don't end up confronting each other head-on.)",
  ui_story_5050_50500303_5_dialog_content = "Hah, we'll soon reach the end of the challenge. Although the difficulty may have increased, we're more than capable of emerging from this triumphant.",
  ui_story_5050_50500303_6_dialog_content = "However, combat is also an art form, and victory cannot simply be won by those who charge into battle fiercely, spear in hand. Without someone behind them to strategize, defeat is inevitable.",
  ui_story_5050_50500303_7_dialog_content = "Joseph, Zhao, we cooperated beautifully out there.",
  ui_story_5050_50500303_8_dialog_content = "There's no need to be overly pessimistic or self-critical due to matters we cannot handle at the moment.",
  ui_story_5050_50500303_9_dialog_content = "There are still a lot of other things we can do.",
  ui_story_5050_50500303_10_dialog_content = "Right. Thank you.",
  ui_story_5050_50500303_11_dialog_content = "I just overreacted a bit, please don't dwell on it too much.",
  ui_story_5050_50500303_12_dialog_content = "Why would I? We're all teammates here, why bother with such trifling matters?",
  ui_story_5050_50500303_13_dialog_content = "We don't know if there will be new challenges in the next stage. We need to take caution as we move forward.",
  ui_story_5050_50500401_1_dialog_content = "Gannon City?",
  ui_story_5050_50500401_2_dialog_content = "It seems so.",
  ui_story_5050_50500401_3_dialog_content = "If I remember correctly, you and Axelia are both natives of Gannon, correct?",
  ui_story_5050_50500401_4_dialog_content = "Your intelligence is as flawless as ever. Indeed, we were born in Gannon City.",
  ui_story_5050_50500401_5_dialog_content = "As do I.",
  ui_story_5050_50500401_6_dialog_content = "So the three of us should have quite the advantage on this map.",
  ui_story_5050_50500401_7_dialog_content = "Yes. This place certainly is filled with a lot of memories.",
  ui_story_5050_50500401_8_dialog_content = "This is also where I met Yingel and Sean.",
  ui_story_5050_50500401_9_dialog_content = "Although life was dull back then, it still felt like we were a little family.",
  ui_story_5050_50500401_10_dialog_content = "Are you up to this, Axelia?",
  ui_story_5050_50500401_11_dialog_content = "Don't worry. I'm fine.",
  ui_story_5050_50500401_12_dialog_content = "Let's go then. We shouldn't make Leo and his team wait too long.",
  ui_story_5050_50500401_13_dialog_content = "...",
  ui_story_5050_50500402_1_dialog_content = "Can you still keep up?",
  ui_story_5050_50500402_2_dialog_content = "No problem.",
  ui_story_5050_50500402_3_dialog_content = "... I'll be alright.",
  ui_story_5050_50500402_4_dialog_content = "The Eclipsite battle simulations are pretty standard, I just never imagined those strange quests would be so tricky.",
  ui_story_5050_50500402_5_dialog_content = "I've been observing the place since we entered, and have noticed that the waypoints are quite different from real-life encounters.",
  ui_story_5050_50500402_6_dialog_content = "Although the concept of quests, resources, cooperation, and so on exist in actual combat situations, they don't have such a rigid mechanical nature.",
  ui_story_5050_50500402_7_dialog_content = "What do you mean?",
  ui_story_5050_50500402_8_dialog_content = "In my personal opinion, Gronru has copied and implemented some comprehensive gameplay elements of a certain video game.",
  ui_story_5050_50500402_9_dialog_content = "I'm not surprised... It certainly sounds like something she'd do.",
  ui_story_5050_50500402_10_dialog_content = "And I speculate that adding such complex mechanisms to the battle simulator may be placing a higher burden on the testers' bodies.",
  ui_story_5050_50500402_11_dialog_content = "Especially testers with a lower level of physical fitness.",
  ui_story_5050_50500402_12_dialog_content = "It's just my theory, but Axelia's performance has been lacking, and I think she's more capable than this.",
  ui_story_5050_50500402_13_dialog_content = "Impressive. I never would've been able to pick up on that...",
  ui_story_5050_50500402_14_dialog_content = "Axelia, would you like to exit the simulator for a while? We wouldn't want this test to affect your performance in the actual Joint Military Exercise...",
  ui_story_5050_50500402_15_dialog_content = "It's not as serious as all that.",
  ui_story_5050_50500402_16_dialog_content = "It won't affect the exercise, I'm confident of that.",
  ui_story_5050_50500402_17_dialog_content = "Alright then, let's make a quick decision and move forward as soon as possible.",
  ui_story_5050_50500403_1_dialog_content = "I can see the exit.",
  ui_story_5050_50500403_2_dialog_content = "We've completed most of the challenges, and it currently looks like the fourth stage is coming to an end.",
  ui_story_5050_50500403_3_dialog_content = "We've been here for so long. PlayerName and the others must be getting impatient waiting on us.",
  ui_story_5050_50500403_4_dialog_content = "There's nothing we can do about that. Although there are only six stages, this test has taken up a lot more time than I expected.",
  ui_story_5050_50500403_5_dialog_content = "Also, Vice knows a lot about mechanics, so PlayerName and the others might clear these stages faster than us.",
  ui_story_5050_50500403_6_dialog_content = "It's okay, let's just go at our own pace.",
  ui_story_5050_50500403_7_dialog_content = "Sorry for making everyone worry about me this whole time...",
  ui_story_5050_50500403_8_dialog_content = "All that matters is that you're okay.",
  ui_story_5050_50500403_9_dialog_content = "Maybe we can join up with them in the next stage.",
  ui_story_5050_50500501_1_dialog_content = "It looks like we're back to the cogoverned Undercity theme in this stage.",
  ui_story_5050_50500501_2_dialog_content = "Yingel, is everything going smoothly on your end?",
  ui_story_5050_50500501_3_dialog_content = "Yep, everything's good for us.",
  ui_story_5050_50500501_4_dialog_content = "I'd just like to confirm one thing with you... Are any of you feeling unwell?",
  ui_story_5050_50500501_5_dialog_content = "... Why do you ask?",
  ui_story_5050_50500501_6_dialog_content = "Axelia's been feeling bad this whole time.",
  ui_story_5050_50500501_7_dialog_content = "I suspect that the overly complex mechanisms of this simulator place an increased burden on people with weak physical constitutions.",
  ui_story_5050_50500501_8_dialog_content = "So that's what's wrong.",
  ui_story_5050_50500501_9_dialog_content = "Hmm, actually I had also noticed.",
  ui_story_5050_50500501_10_dialog_content = "Hi, everyone!",
  ui_story_5050_50500501_11_dialog_content = "Sorry, I've been running a test on the simulator, just heard your conversation.",
  ui_story_5050_50500501_12_dialog_content = "I really didn't consider the physical effect the simulator might have on its users...",
  ui_story_5050_50500501_13_dialog_content = "But it seems that most of Anatoli's deductions are correct.",
  ui_story_5050_50500501_14_dialog_content = "This is a relatively significant issue. Maybe Zhao and Axelia should come out and take a rest?",
  ui_story_5050_50500501_15_dialog_content = "There's no need.",
  ui_story_5050_50500501_16_dialog_content = "Y-You're really that determined?",
  ui_story_5050_50500501_17_dialog_content = "I have faith in my body. I'll ask to rest when necessary.",
  ui_story_5050_50500501_18_dialog_content = "Same here.",
  ui_story_5050_50500501_19_dialog_content = "We're nearing the end. Let's get this over with.",
  ui_story_5050_50500501_20_dialog_content = "If they insist, let's respect the opinions of the parties involved.",
  ui_story_5050_50500501_21_dialog_content = "Okay, I'll also be keeping an eye on everyone's situation at all times.",
  ui_story_5050_50500501_22_dialog_content = "This stage seems to have a cooperative unlocking section. Leo, we're counting on you.",
  ui_story_5050_50500501_23_dialog_content = "Don't worry, let's solve this in one go.",
  ui_story_5050_50500502_1_dialog_content = "It seems that this stage has an Undercity theme.",
  ui_story_5050_50500502_2_dialog_content = "It looks like we'll need Leo and the others to help us unlock the path ahead before we can pass through.",
  ui_story_5050_50500502_3_dialog_content = "Right. Let's take a break here while we wait.",
  ui_story_5050_50500502_4_dialog_content = "Sigh...",
  ui_story_5050_50500502_5_dialog_content = "(Axelia seems really tired.)",
  ui_story_5050_50500502_6_dialog_content = "(I never expected that little Aurorian from the orphanage all those years ago would grow up to be so strong.)",
  ui_story_5050_50500502_7_dialog_content = "(Looking back, it seems like it was only yesterday.)",
  ui_story_5050_50500502_8_dialog_content = "... Thinking about something?",
  ui_story_5050_50500502_9_dialog_content = "Just remembering the past.",
  ui_story_5050_50500502_10_dialog_content = "Childhood memories?",
  ui_story_5050_50500502_11_dialog_content = "Why do you say that?",
  ui_story_5050_50500502_12_dialog_content = "Don't underestimate the reach of my intelligence network. You and Axelia have known each other since you were children. I know all about it.",
  ui_story_5050_50500502_13_dialog_content = "Yes, we've known each other since we were very young.",
  ui_story_5050_50500502_14_dialog_content = "Fighting alongside an old acquaintance you truly trust is an enviable thing, from a certain perspective.",
  ui_story_5050_50500502_15_dialog_content = "Do you have anyone like that?",
  ui_story_5050_50500502_16_dialog_content = "...",
  ui_story_5050_50500502_17_dialog_content = "Let's stop chatting for now, we wouldn't want to wake her up.",
  ui_story_5050_50500503_1_dialog_content = "Although this doesn't really qualify as intensive battle training, this simulation still requires significant physical exertion. Are you alright?",
  ui_story_5050_50500503_2_dialog_content = "I'm fine. Zhao?",
  ui_story_5050_50500503_3_dialog_content = "I'm fine too.",
  ui_story_5050_50500503_4_dialog_content = "<size=45>?!</size>",
  ui_story_5050_50500503_5_dialog_content = "What's all this about?",
  ui_story_5050_50500503_6_dialog_content = "Yikes! Sorry!",
  ui_story_5050_50500503_7_dialog_content = "This is a known bug... Sometimes, the wrong map loads up.",
  ui_story_5050_50500503_8_dialog_content = "But don't worry, it won't have any impact on your progress!",
  ui_story_5050_50500503_9_dialog_content = "I noticed before that there are obvious gaps in the connections between some rooms in the stages.",
  ui_story_5050_50500503_10_dialog_content = "But I haven't seen any of these gaps on the paths where you can encounter Eclipsites.",
  ui_story_5050_50500503_11_dialog_content = "I'm guessing those rooms are all just randomly generated, correct?",
  ui_story_5050_50500503_12_dialog_content = "<size=45>!!!</size>",
  ui_story_5050_50500503_13_dialog_content = "Don't try randomly guessing the designer's thoughts!",
  ui_story_5050_50500503_14_dialog_content = "It's confidential! Confidential!",
  ui_story_5050_50500503_15_dialog_content = "Zhao, your powers of observation are extremely sharp.",
  ui_story_5050_50500503_16_dialog_content = "You truly are worthy of your reputation as Illumina's peerless strategist, being able to pick up on such minute details.",
  ui_story_5050_50500503_17_dialog_content = "That's a little bit over the top. I've just gotten used to observing details on the battlefield.",
  ui_story_5050_50500503_18_dialog_content = "Alright! Don't worry about these small details, just go on to the next stage quickly! The last stage won't be easy!",
  ui_story_5050_50500503_19_dialog_content = "Hehe, it still won't get the better of us! Let's go!",
  ui_story_5050_50500504_1_dialog_content = "It seems we're about to reach the final stage.",
  ui_story_5050_50500504_2_dialog_content = "The final stage won't be easy... Get your heads in the game, everyone.",
  ui_story_5050_50500504_3_dialog_content = "Yingel, how are you doing on your end? Have you reached the exit yet?",
  ui_story_5050_50500504_4_dialog_content = "We're almost there.",
  ui_story_5050_50500504_5_dialog_content = "Is Axelia okay?",
  ui_story_5050_50500504_6_dialog_content = "Don't worry, I just had a rest and feel much better now.",
  ui_story_5050_50500504_7_dialog_content = "I'm in top form and ready to face the final challenge head-on.",
  ui_story_5050_50500504_8_dialog_content = "Haha, glad to hear it!",
  ui_story_5050_50500504_9_dialog_content = "We'll see you at the final stage!",
  ui_story_5050_50500504_10_dialog_content = "Okay, let's quickly move ahead.",
  ui_story_5050_50500601_1_dialog_content = "...",
  ui_story_5050_50500601_2_dialog_content = "What's wrong, Leo? Are you feeling okay?",
  ui_story_5050_50500601_3_dialog_content = "No one has ever asked me that before... Rest assured, my fortitude knows no bounds.",
  ui_story_5050_50500601_4_dialog_content = "Captain Leo, is it because we're in Lumopolis?",
  ui_story_5050_50500601_5_dialog_content = "You're from Lumopolis. This map must feel very familiar to you.",
  ui_story_5050_50500601_6_dialog_content = "... Haha, and I've never had someone guess what I was thinking so easily before.",
  ui_story_5050_50500601_7_dialog_content = "You're right, I cannot deny it—I was born here.",
  ui_story_5050_50500601_8_dialog_content = "Lumopolis has given me much, yet it has also taken much away from me.",
  ui_story_5050_50500601_9_dialog_content = "A banished nobles cast from Uptown to an area infinitely close to the Eternal Night. Even if you died, you're nothing more than a rotting corpse, mourned by no one.",
  ui_story_5050_50500601_10_dialog_content = "Naturally, I had many unforgettable experiences, but they also slowly changed the way I thought.",
  ui_story_5050_50500601_11_dialog_content = "Leo...",
  ui_story_5050_50500601_12_dialog_content = "...",
  ui_story_5050_50500601_13_dialog_content = "I didn't mean to ramble on like that. All you need to know is that I currently have only one goal—to fight the Eclipsites with all those willing to stand beside me.",
  ui_story_5050_50500601_14_dialog_content = "We can talk about other matters at our leisure when we have some free time in the future.",
  ui_story_5050_50500601_15_dialog_content = "Excellent. I'd love to hear more.",
  ui_story_5050_50500601_16_dialog_content = "Leo, have you also arrived in Lumopolis over there?",
  ui_story_5050_50500601_17_dialog_content = "Yes, we're on the Uptown map.",
  ui_story_5050_50500601_18_dialog_content = "We should meet near the end. Keep going, everyone.",
  ui_story_5050_50500601_19_dialog_content = "You too. Stay safe.",
  ui_story_5050_50500601_20_dialog_content = "Let's move out!",
  ui_story_5050_50500602_1_dialog_content = "Is this... Lumopolis?",
  ui_story_5050_50500602_2_dialog_content = "I've never been here before.",
  ui_story_5050_50500602_3_dialog_content = "Judging from the layout here, this should be Lower Lumopolis. It certainly has a unique style.",
  ui_story_5050_50500602_4_dialog_content = "The three of us are all stationed in Illumina. We haven't had the chance to familiarize ourselves with Lumopolis.",
  ui_story_5050_50500602_5_dialog_content = "We should take this opportunity to have a look around.",
  ui_story_5050_50500602_6_dialog_content = "Lumopolis...",
  ui_story_5050_50500602_7_dialog_content = "Anatoli, do you have something against Lumopolis?",
  ui_story_5050_50500602_8_dialog_content = "I consider myself a centrist in this matter. Although the bond between Illumina and Lumopolis is somewhat delicate, I don't lean toward either side.",
  ui_story_5050_50500602_9_dialog_content = "We all have the same goals and hopes for a brighter tomorrow. Why use such factions to deliberately sow hostility and prejudice?",
  ui_story_5050_50500602_10_dialog_content = "That's exactly the kind of answer I expected from you.",
  ui_story_5050_50500602_11_dialog_content = "No matter where you're from or which faction you belong to, we all now have only one common goal.",
  ui_story_5050_50500602_12_dialog_content = "Perhaps occasionally looking at a problem from a different perspective could make things easier.",
  ui_story_5050_50500602_13_dialog_content = "The final stage, should be challenging.",
  ui_story_5050_50500602_14_dialog_content = "Yes. I wonder if there'll be any special stage challenges...",
  ui_story_5050_50500602_15_dialog_content = "Let's go!",
  ui_story_5050_50500603_1_dialog_content = "Leo! We're finally back together.",
  ui_story_5050_50500603_2_dialog_content = "I have to admit that we worked very well together, otherwise we wouldn't have reached the finish line so quickly.",
  ui_story_5050_50500603_3_dialog_content = "But I didn't quite understand some of the quests. Those were headaches.",
  ui_story_5050_50500603_4_dialog_content = "It was all thanks to everyone's concerted efforts that we made it.",
  ui_story_5050_50500603_5_dialog_content = "Axelia, how are you holding up?",
  ui_story_5050_50500603_6_dialog_content = "I'm feeling a hundred percent.",
  ui_story_5050_50500603_7_dialog_content = "Praise be to the God of Light for the blessings. It's the power of our mutual trust that has made our journey so successful.",
  ui_story_5050_50500603_8_dialog_content = "Wow! Great work! Congratulations on reaching the finish line!",
  ui_story_5050_50500603_9_dialog_content = "Did you enjoy the training?",
  ui_story_5050_50500603_10_dialog_content = "It might be different from the practical training you're used to, but it also helps to work on a range of abilities, making it equally rewarding.",
  ui_story_5050_50500603_11_dialog_content = "This was a rare experience for us to become more familiar with each other's abilities through close cooperation.",
  ui_story_5050_50500603_12_dialog_content = "Heheh, another classic Gronru production, developed over several sleepless days and nights!",
  ui_story_5050_50500603_13_dialog_content = "Another small suggestion—perhaps you should rework the voice-controlled password on the Colossus map.",
  ui_story_5050_50500603_14_dialog_content = "Huh? Oh...",
  ui_story_5050_50500603_15_dialog_content = "<size=45>Whaaat?!?! I didn't change it?!</size>",
  ui_story_5050_50500603_16_dialog_content = "<size=45>Th-That was just something I added at random while debugging!</size>",
  ui_story_5050_50500603_17_dialog_content = "It's okay... Only a few of us know the password right now.",
  ui_story_5050_50500603_18_dialog_content = "And then there's just Vice, Carleen, and PlayerName up next.",
  ui_story_5050_50500603_19_dialog_content = "You're not making me feel any better.",
  ui_story_5050_50500603_20_dialog_content = "Ahem... Anyway, good work, everyone. Don't let the remaining teams wait too long—prepare yourselves...",
  ui_story_5050_50500603_21_dialog_content = "<color=#e8d9bb>Rumble, rumble...</color>",
  ui_story_5050_50500603_22_dialog_content = "Is that an earthquake?",
  ui_story_5050_50500603_23_dialog_content = "... What's going on? Why did the system suddenly report an error?!",
  ui_story_5050_50500603_24_dialog_content = "Watch your step, everyone!",
  ui_story_5050_50500603_25_dialog_content = "<size=45>?!</size>",
  ui_story_5050_50500603_26_dialog_content = "The map's changing.",
  ui_story_5050_50500603_27_dialog_content = "They're all the stages we've been to before. Is there something wrong with the system?",
  ui_story_5050_50500603_28_dialog_content = "Aaah! Everyone, please wait a moment—I'm fixing it!",
  ui_story_5050_50500603_29_dialog_content = "<color=#e8d9bb>A few minutes later...</color>",
  ui_story_5050_50500603_30_dialog_content = "Phew... It should be fine now.",
  ui_story_5050_50500603_31_dialog_content = "Sorry, there may have been some minor bugs left in the last part.",
  ui_story_5050_50500603_32_dialog_content = "I guess I didn't debug the final stage thoroughly enough.",
  ui_story_5050_50500603_33_dialog_content = "Is that thing up ahead one of your bugs too?",
  ui_story_5050_50500603_34_dialog_content = "Huh? What?",
  ui_story_5050_50500603_35_dialog_content = "<anim type=Shake><size=45>Graah! Graaah!</size></anim>",
  ui_story_5050_50500603_36_dialog_content = "Wh-What is that?! I don't remember adding anything like that to the sim!",
  ui_story_5050_50500603_37_dialog_content = "There's no choice but to take it on.",
  ui_story_5050_50500603_38_dialog_content = "Think of it as an impromptu training session! Let's go!",
  ui_story_5050_50500604_1_dialog_content = "<size=45>Great work, everyone! Congratulations on completing the stage!</size>",
  ui_story_5050_50500604_2_dialog_content = "You know, beating that last Eclipsite that just appeared out of the clear blue sky was a lot tougher than all the previous stages.",
  ui_story_5050_50500604_3_dialog_content = "Hah, but it was indeed a rare chance for some truly challenging combat training. We may face even stronger enemies on the battlefield.",
  ui_story_5050_50500604_4_dialog_content = "Indeed. The bug was more exciting than the actual stages.",
  ui_story_5050_50500604_5_dialog_content = "Y-You can't say that kind of thing to a designer!",
  ui_story_5050_50500604_6_dialog_content = "But whether fighting with the Ironthorn Knights or in the Joint Military Exercise, cooperation is essential to combat.",
  ui_story_5050_50500604_7_dialog_content = "One person alone is limited in what they can achieve. Even as a leader, fighting alone is just like being a wavering sapling in the darkness.",
  ui_story_5050_50500604_8_dialog_content = "Companions are the light, the water, and the sublime power that can turn a sapling into a majestic tree.",
  ui_story_5050_50500604_9_dialog_content = "Our victories are based on the efforts of each of our comrades.",
  ui_story_5050_50500604_10_dialog_content = "It's not every day one gets to hear Leo make such an emotional speech.",
  ui_story_5050_50500604_11_dialog_content = "I was just expressing my sentiments.",
  ui_story_5050_50500604_12_dialog_content = "When facing such complex quests, a single person is like a headless fly without a team working together for a common cause.",
  ui_story_5050_50500604_13_dialog_content = "I'm also very grateful for everyone's help.",
  ui_story_5050_50500604_14_dialog_content = "I just did what I thought was right.",
  ui_story_5050_50500604_15_dialog_content = "At this moment, let us accept this warm kindness with peace in our hearts. May the God of Light bless all our trusted companions and us.",
  ui_story_5050_50500604_16_dialog_content = "So, which game served as the basis for this simulation?",
  ui_story_5050_50500604_17_dialog_content = "Actually, it was Sword of the—I mean, I designed it myself!",
  ui_story_5050_50500604_18_dialog_content = "Oh. That's very impressive.",
  ui_story_5050_50500604_19_dialog_content = "But next time, you should think about erasing the original developer's logo from the game's assets.",
  ui_story_5050_50500604_20_dialog_content = "<size=45>!!!</size>",
  ui_story_5050_50500604_21_dialog_content = "Did you discover all the flaws in my game? You're one sharp intelligence officer.",
  ui_story_5050_50500604_22_dialog_content = "Alright, don't tease her. This was a very meaningful training session for us all.",
  ui_story_5050_50500604_23_dialog_content = "Why haven't PlayerName, Beretta, and the others come over yet? They must be tired of waiting.",
  ui_story_5050_50500604_24_dialog_content = "Remember what I said, there are elements of exploration and puzzle-solving in this sim, so it's best if we let them avoid any potential spoilers.",
  ui_story_5050_50500604_25_dialog_content = "However, there were not too many system issues during the testing process, so I'd say it was quite successful!",
  ui_story_5050_50500604_26_dialog_content = "So, let's let PlayerName and the others experience it all for themselves!",
  ui_story_5050_50500604_27_dialog_content = "Leo, Yingel, please go and tell them to come on in!"
}
return config
